// A HUD panel with one line of text, built once when the round starts.
//
// A widget is one box on the screen. A container is an empty box you put other
// widgets inside. Every widget has a name, and the name is how you find it again.

const PANEL = "faqPanel";
const LINE = "faqPanelLine";

export function OnGameModeStarted(): void {
    // Position and size are measured on a 1920 by 1080 safe area.
    // The offset runs inward from the anchored edge, so 24, 24 under TopLeft
    // means 24 pixels in from the left and 24 pixels down from the top.
    mod.AddUIContainer(
        PANEL,
        mod.CreateVector(24, 24, 0), // offset from the anchor
        mod.CreateVector(420, 96, 0), // width and height
        mod.UIAnchor.TopLeft,
        mod.GetUIRoot(), // parent: the whole screen
        true, // visible
        8, // padding
        mod.CreateVector(0, 0, 0), // background colour, red green blue, each 0 to 1
        0.7, // background alpha, 0 is invisible and 1 is opaque
        mod.UIBgFill.Solid,
        mod.UIDepth.AboveGameUI // draw over the normal game HUD
    );

    // AddUIContainer returns nothing, so ask for the widget back by its name.
    const panel = mod.FindUIWidgetWithName(PANEL) as mod.UIWidget;

    mod.AddUIText(
        LINE,
        mod.CreateVector(0, 0, 0),
        mod.CreateVector(404, 80, 0),
        mod.UIAnchor.Center, // centred inside the panel, not the screen
        panel, // parent is the panel, so the text moves with it
        true,
        0,
        mod.CreateVector(0, 0, 0),
        0, // no background of its own
        mod.UIBgFill.None,
        mod.Message(mod.stringkeys.faq.panel.ready), // text must come from strings.json
        28, // text size
        mod.CreateVector(1, 1, 1), // text colour, white
        1, // text alpha
        mod.UIAnchor.Center, // where the text sits inside its own box
        mod.UIDepth.AboveGameUI
    );
}

// Proof of how UI offsets work: four identical boxes at the same 24, 24 offset,
// one under each corner anchor. They land one in each corner of the screen.
//
// The offset is an INWARD inset from the edge the anchor names. Under a Right
// anchor a bigger x moves the box further LEFT, and under a Bottom anchor a
// bigger y moves it further UP. Nothing here is a screen coordinate.

const CORNERS: { name: string; anchor: mod.UIAnchor }[] = [
    { name: "faqCornerTopLeft", anchor: mod.UIAnchor.TopLeft },
    { name: "faqCornerTopRight", anchor: mod.UIAnchor.TopRight },
    { name: "faqCornerBottomLeft", anchor: mod.UIAnchor.BottomLeft },
    { name: "faqCornerBottomRight", anchor: mod.UIAnchor.BottomRight },
];

export function OnGameModeStarted(): void {
    for (const corner of CORNERS) {
        mod.AddUIContainer(
            corner.name,
            mod.CreateVector(24, 24, 0), // the SAME offset for all four
            mod.CreateVector(200, 120, 0),
            corner.anchor,
            mod.GetUIRoot(),
            true,
            0,
            mod.CreateVector(1, 0.514, 0.38),
            0.6,
            mod.UIBgFill.Solid,
            mod.UIDepth.AboveGameUI
        );
    }
}

// A round timer that counts up once a second.
//
// The widgets are created ONCE. After that only the label changes. Deleting and
// rebuilding a widget every tick leaks memory until the script stops running.

const PANEL = "faqClockPanel";
const LINE = "faqClockLine";

let clockLine: mod.UIWidget | undefined;
let seconds = 0;

function build(): void {
    mod.AddUIContainer(
        PANEL,
        mod.CreateVector(0, 24, 0),
        mod.CreateVector(240, 72, 0),
        mod.UIAnchor.TopCenter,
        mod.GetUIRoot(),
        true,
        6,
        mod.CreateVector(0, 0, 0),
        0.7,
        mod.UIBgFill.Solid,
        mod.UIDepth.AboveGameUI
    );

    const panel = mod.FindUIWidgetWithName(PANEL) as mod.UIWidget;

    mod.AddUIText(
        LINE,
        mod.CreateVector(0, 0, 0),
        mod.CreateVector(228, 60, 0),
        mod.UIAnchor.Center,
        panel,
        true,
        0,
        mod.CreateVector(0, 0, 0),
        0,
        mod.UIBgFill.None,
        mod.Message(mod.stringkeys.faq.clock.line, 0),
        32,
        mod.CreateVector(1, 1, 1),
        1,
        mod.UIAnchor.Center,
        mod.UIDepth.AboveGameUI
    );

    clockLine = mod.FindUIWidgetWithName(LINE) as mod.UIWidget;
}

export async function OnGameModeStarted(): Promise<void> {
    build();

    while (true) {
        await mod.Wait(1);
        seconds = seconds + 1;

        // One cheap call. No AddUI, no DeleteUIWidget, no rebuild.
        if (clockLine !== undefined) {
            mod.SetUITextLabel(clockLine, mod.Message(mod.stringkeys.faq.clock.line, seconds));
        }
    }
}

// Two buttons, and telling them apart when one is pressed.
//
// Comparing the widget you are handed against a stored widget with == does not
// work. Compare the widget's NAME instead, which is a plain string.

const MENU = "faqMenu";
const BTN_YES = "faqBtnYes";
const BTN_NO = "faqBtnNo";

function addButton(name: string, y: number, label: mod.Message, parent: mod.UIWidget): void {
    mod.AddUIButton(
        name,
        mod.CreateVector(0, y, 0),
        mod.CreateVector(240, 56, 0),
        mod.UIAnchor.TopCenter,
        parent,
        true,
        0,
        mod.CreateVector(0.1, 0.1, 0.1),
        1,
        mod.UIBgFill.Solid,
        true, // button enabled
        mod.CreateVector(0.1, 0.1, 0.1), // base colour
        1,
        mod.CreateVector(0.2, 0.2, 0.2), // disabled colour
        0.5,
        mod.CreateVector(1, 0.514, 0.38), // pressed colour
        1,
        mod.CreateVector(0.3, 0.3, 0.3), // hover colour
        1,
        mod.CreateVector(0.25, 0.25, 0.25), // focused colour
        1
    );

    const button = mod.FindUIWidgetWithName(name) as mod.UIWidget;

    mod.AddUIText(
        name + "Label",
        mod.CreateVector(0, 0, 0),
        mod.CreateVector(230, 50, 0),
        mod.UIAnchor.Center,
        button,
        true,
        0,
        mod.CreateVector(0, 0, 0),
        0,
        mod.UIBgFill.None,
        label,
        24,
        mod.CreateVector(1, 1, 1),
        1,
        mod.UIAnchor.Center,
        mod.UIDepth.AboveGameUI
    );
}

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    mod.AddUIContainer(
        MENU,
        mod.CreateVector(0, 200, 0),
        mod.CreateVector(280, 140, 0),
        mod.UIAnchor.TopCenter,
        mod.GetUIRoot(),
        true,
        10,
        mod.CreateVector(0, 0, 0),
        0.8,
        mod.UIBgFill.Solid,
        mod.UIDepth.AboveGameUI,
        eventPlayer // only this player sees it
    );

    const menu = mod.FindUIWidgetWithName(MENU) as mod.UIWidget;
    addButton(BTN_YES, 0, mod.Message(mod.stringkeys.faq.menu.yes), menu);
    addButton(BTN_NO, 64, mod.Message(mod.stringkeys.faq.menu.no), menu);

    // Give the player a mouse cursor so the buttons can be clicked.
    mod.EnableUIInputMode(true, eventPlayer);
}

export function OnPlayerUIButtonEvent(
    eventPlayer: mod.Player,
    eventUIWidget: mod.UIWidget,
    eventUIButtonEvent: mod.UIButtonEvent
): void {
    if (eventUIButtonEvent !== mod.UIButtonEvent.ButtonUp) return;

    const pressed = mod.GetUIWidgetName(eventUIWidget);

    if (pressed === BTN_YES) {
        mod.DisplayNotificationMessage(mod.Message(mod.stringkeys.faq.menu.pickedYes), eventPlayer);
    } else if (pressed === BTN_NO) {
        mod.DisplayNotificationMessage(mod.Message(mod.stringkeys.faq.menu.pickedNo), eventPlayer);
    }

    mod.EnableUIInputMode(false, eventPlayer);
}

// Showing and hiding a panel, and taking it down once at the end of the round.
//
// Deleting a container also deletes everything inside it. Deleting a child after
// its parent is already gone frees the same memory twice and crashes the server,
// so delete the ROOT only, and forget your references to the children.

const PANEL = "faqTeardownPanel";
const LINE = "faqTeardownLine";

let panel: mod.UIWidget | undefined;

export function OnGameModeStarted(): void {
    mod.AddUIContainer(
        PANEL,
        mod.CreateVector(24, 24, 0),
        mod.CreateVector(360, 80, 0),
        mod.UIAnchor.BottomLeft,
        mod.GetUIRoot(),
        true,
        8,
        mod.CreateVector(0, 0, 0),
        0.7,
        mod.UIBgFill.Solid,
        mod.UIDepth.AboveGameUI
    );

    panel = mod.FindUIWidgetWithName(PANEL) as mod.UIWidget;

    mod.AddUIText(
        LINE,
        mod.CreateVector(0, 0, 0),
        mod.CreateVector(344, 64, 0),
        mod.UIAnchor.Center,
        panel,
        true,
        0,
        mod.CreateVector(0, 0, 0),
        0,
        mod.UIBgFill.None,
        mod.Message(mod.stringkeys.faq.teardown.line),
        24,
        mod.CreateVector(1, 1, 1),
        1,
        mod.UIAnchor.Center,
        mod.UIDepth.AboveGameUI
    );
}

// To hide it during play, do NOT delete it. Hiding is free and reversible.
export function hidePanel(): void {
    if (panel !== undefined) mod.SetUIWidgetVisible(panel, false);
}

export function showPanel(): void {
    if (panel !== undefined) mod.SetUIWidgetVisible(panel, true);
}

export function OnGameModeEnding(): void {
    if (panel === undefined) return;

    // One delete, on the root. The text widget inside goes with it.
    mod.DeleteUIWidget(panel);
    panel = undefined; // never call DeleteUIWidget on this handle again
}

// A panel that only one player sees, rebuilt for every player as they deploy,
// including players who join in the middle of a round.
//
// The last argument of the AddUI calls is the receiver. Leave it out and every
// player on the server gets the widget. Pass a player and only that player sees
// it. Pass a team and only that team sees it.
//
// Build it on OnPlayerDeployed, not on OnPlayerJoinGame: a joining player is not
// on their final team yet, so a team targeted widget built that early can miss.

const built: number[] = [];

function panelName(player: mod.Player): string {
    return "faqOwnPanel_" + mod.GetObjId(player);
}

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    const id = mod.GetObjId(eventPlayer);
    if (built.indexOf(id) !== -1) return; // already has one, do not build twice

    built.push(id);

    const name = panelName(eventPlayer);

    mod.AddUIContainer(
        name,
        mod.CreateVector(24, 120, 0),
        mod.CreateVector(320, 72, 0),
        mod.UIAnchor.TopRight, // 24 in from the RIGHT edge, 120 down from the top
        mod.GetUIRoot(),
        true,
        8,
        mod.CreateVector(0, 0, 0),
        0.7,
        mod.UIBgFill.Solid,
        mod.UIDepth.AboveGameUI,
        eventPlayer // the receiver
    );

    const panel = mod.FindUIWidgetWithName(name) as mod.UIWidget;

    mod.AddUIText(
        name + "Line",
        mod.CreateVector(0, 0, 0),
        mod.CreateVector(304, 56, 0),
        mod.UIAnchor.Center,
        panel,
        true,
        0,
        mod.CreateVector(0, 0, 0),
        0,
        mod.UIBgFill.None,
        mod.Message(mod.stringkeys.faq.own.greeting, eventPlayer),
        24,
        mod.CreateVector(1, 1, 1),
        1,
        mod.UIAnchor.Center,
        mod.UIDepth.AboveGameUI,
        eventPlayer
    );
}

// Careful: this handler is given the leaving player id as a plain number, not a
// Player. Getting a handler signature wrong is a common cause of a mod that will
// not save.
export function OnPlayerLeaveGame(eventNumber: number): void {
    const at = built.indexOf(eventNumber);
    if (at !== -1) built.splice(at, 1);
}

// The three ways to put a line of text on screen without building any widgets.
// Use these for a quick message. Build a panel only when the text has to stay put.

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    // 1. A notification in the top right, for a few seconds.
    //    No receiver means everyone sees it; pass a player or a team to narrow it.
    mod.DisplayNotificationMessage(mod.Message(mod.stringkeys.faq.quick.welcome), eventPlayer);

    // 2. A highlighted line in the kill log on the left.
    mod.DisplayHighlightedWorldLogMessage(mod.Message(mod.stringkeys.faq.quick.joined, eventPlayer));

    // 3. A custom notification with named slots. The header and up to four
    //    message lines are separate calls, and the number is how long it stays.
    mod.DisplayCustomNotificationMessage(
        mod.Message(mod.stringkeys.faq.quick.header),
        mod.CustomNotificationSlots.HeaderText,
        6,
        eventPlayer
    );
    mod.DisplayCustomNotificationMessage(
        mod.Message(mod.stringkeys.faq.quick.body),
        mod.CustomNotificationSlots.MessageText1,
        6,
        eventPlayer
    );
}

// Every piece of text a player can see has to exist in strings.json first.
//
// mod.Message will NOT take a plain string you typed in the script. It accepts
// a key from mod.stringkeys, a number, or a player. Passing "Hello" gives you a
// mod that either refuses to save or shows nothing.

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    // WRONG, and the reason most first mods show no text at all:
    //   mod.DisplayNotificationMessage(mod.Message("Hello"), eventPlayer);

    // RIGHT. The key comes from strings.json, which sits next to this file.
    mod.DisplayNotificationMessage(mod.Message(mod.stringkeys.faq.text.hello), eventPlayer);

    // Keys can be nested as deep as you like. The nesting in the script has to
    // match the nesting in the file exactly, including capital letters.
    mod.DisplayHighlightedWorldLogMessage(mod.Message(mod.stringkeys.faq.text.rules.noVehicles));
}

// Plain strings are still fine anywhere the PLAYER never sees them: widget
// names, object lookups, console.log, your own comparisons.
export function OnGameModeStarted(): void {
    const internalName = "faqInternalOnly";
    console.log("boot: " + internalName);
}

// Putting numbers, player names and other strings into your text.
//
// In strings.json write {} where the value goes. A template can hold at most
// THREE of them, because mod.Message takes the template plus three arguments and
// no more. Each argument is a number, a player, or another mod.stringkeys value.

let squadScore = 0;

export function OnPlayerEarnedKill(
    eventPlayer: mod.Player,
    eventOtherPlayer: mod.Player,
    eventDeathType: mod.DeathType,
    eventWeaponUnlock: mod.WeaponUnlock
): void {
    squadScore = squadScore + 1;

    // One argument: a number.
    mod.DisplayNotificationMessage(mod.Message(mod.stringkeys.faq.args.score, squadScore), eventPlayer);

    // Two arguments: a player, then a number. The game writes the player's name.
    mod.DisplayHighlightedWorldLogMessage(
        mod.Message(mod.stringkeys.faq.args.playerScore, eventPlayer, squadScore)
    );

    // Three arguments, the maximum. One of them is another key from
    // strings.json, which is how you pick between two words at runtime.
    const how = squadScore >= 10 ? mod.stringkeys.faq.args.onFire : mod.stringkeys.faq.args.steady;
    mod.DisplayHighlightedWorldLogMessage(
        mod.Message(mod.stringkeys.faq.args.kill, eventPlayer, eventOtherPlayer, how)
    );
}

// The in game font only carries plain ASCII, and the upload only accepts it too.
//
// A character above U+00FF anywhere in the script or in strings.json makes the
// upload fail, and that includes characters inside a COMMENT. Characters that do
// survive the upload but are not in the font are drawn as an empty box.
//
// So: no accents, no emoji, no curly quotes, no arrows, no box drawing. Write
// every label in the plain letters, digits and punctuation on a US keyboard.

export function OnGameModeStarted(): void {
    // These labels are all safe.
    mod.DisplayHighlightedWorldLogMessage(mod.Message(mod.stringkeys.faq.ascii.title));
    mod.DisplayHighlightedWorldLogMessage(mod.Message(mod.stringkeys.faq.ascii.arrow));
    mod.DisplayHighlightedWorldLogMessage(mod.Message(mod.stringkeys.faq.ascii.bullet));
    mod.DisplayHighlightedWorldLogMessage(mod.Message(mod.stringkeys.faq.ascii.quote));
}

// Playing a sound effect, and stopping it again.
//
// A sound needs a carrier object. Either place an SFX object in the map in the
// editor and fetch it with mod.GetSFX(objectId), or spawn one at runtime from
// the mod.RuntimeSpawn_Common list. Spawn the carriers you will need at game
// start, not at the moment you want the sound.
//
// The second argument of PlaySound is amplitude: a multiplier, where 1 is the
// sound's normal loudness. The four argument form adds a position and a range in
// metres, which is roughly how far away the sound fades to nothing.

let alarm: mod.SFX | undefined;
let stinger: mod.SFX | undefined;

export function OnGameModeStarted(): void {
    const origin = mod.CreateVector(0, 0, 0);

    // A looping 3D alarm. A 3D sound plays at the position of its carrier
    // object, and the carrier cannot be moved once it is placed, so spawn one
    // carrier per place you want the sound to come from.
    alarm = mod.SpawnObject(mod.RuntimeSpawn_Common.SFX_Alarm, origin, origin) as mod.SFX;

    // A 2D interface sting, heard at the same loudness wherever the player is.
    stinger = mod.SpawnObject(
        mod.RuntimeSpawn_Common.SFX_UI_Gamemode_Shared_CaptureObjectives_CaptureNeutralize_OneShot2D,
        origin,
        origin
    ) as mod.SFX;
}

export function OnCapturePointCaptured(eventCapturePoint: mod.CapturePoint): void {
    if (stinger === undefined) return;

    // 2D, everyone hears it, normal loudness.
    mod.PlaySound(stinger, 1);
}

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    if (alarm === undefined) return;

    // 3D, only this player hears it, audible out to about 40 metres.
    mod.PlaySound(alarm, 0.8, mod.CreateVector(0, 0, 0), 40, eventPlayer);
}

export function OnGameModeEnding(): void {
    if (alarm === undefined) return;

    // No receiver stops it for everyone. Pass a player, squad or team to stop it
    // for just them, which is how one carrier serves several groups at once.
    mod.StopSound(alarm);
}

// Getting the announcer to speak.
//
// A voice over needs its own carrier, spawned from SFX_VOModule_OneShot2D.
// Spawn the carriers at game start and wait at least one tick before playing
// anything through them: spawning and playing in the same tick is silent.
//
// PlayVO always needs a flag, even for lines that have nothing to do with a
// flag. Use Alpha as the stand in. Objective and MCom lines are played with NO
// receiver, so the whole server hears them. Lines that are relative to a side,
// such as who is winning, take a team as the fourth argument.
//
// Several announcer events are silent in the retail game whatever you do. When a
// line refuses to play, use one of the SFX_UI_Gamemode_Shared_CaptureObjectives
// stingers instead, which always work. There is one at the bottom of this file.

const LETTERS: mod.VoiceOverFlags[] = [
    mod.VoiceOverFlags.Alpha,
    mod.VoiceOverFlags.Bravo,
    mod.VoiceOverFlags.Charlie,
    mod.VoiceOverFlags.Delta,
    mod.VoiceOverFlags.Echo,
    mod.VoiceOverFlags.Foxtrot,
    mod.VoiceOverFlags.Golf,
    mod.VoiceOverFlags.Hotel,
    mod.VoiceOverFlags.India,
];

const carriers: mod.VO[] = [];
let stinger: mod.SFX | undefined;

export async function OnGameModeStarted(): Promise<void> {
    const origin = mod.CreateVector(0, 0, 0);

    // One carrier per flag letter, all spawned now, long before anything speaks.
    for (let i = 0; i < LETTERS.length; i++) {
        carriers.push(
            mod.SpawnObject(mod.RuntimeSpawn_Common.SFX_VOModule_OneShot2D, origin, origin) as mod.VO
        );
    }

    stinger = mod.SpawnObject(
        mod.RuntimeSpawn_Common.SFX_UI_Gamemode_Shared_CaptureObjectives_CaptureStartedByFriendly_OneShot2D,
        origin,
        origin
    ) as mod.SFX;

    // Let a tick pass so the carriers are ready.
    await mod.Wait(1);
}

// letterIndex 0 is Alpha, 1 is Bravo and so on.
function sayObjective(event: mod.VoiceOverEvents2D, letterIndex: number): void {
    if (carriers.length === 0) return;

    const i = letterIndex < carriers.length ? letterIndex : 0;

    // No fourth argument: the whole server hears it.
    mod.PlayVO(carriers[i], event, LETTERS[i]);
}

function sayTeamLine(event: mod.VoiceOverEvents2D, team: mod.Team): void {
    if (carriers.length === 0) return;

    // A team relative line takes the team. Alpha is the stand in flag.
    mod.PlayVO(carriers[0], event, mod.VoiceOverFlags.Alpha, team);
}

export function OnCapturePointCaptured(eventCapturePoint: mod.CapturePoint): void {
    sayObjective(mod.VoiceOverEvents2D.ObjectiveCaptured, 0);
    sayTeamLine(mod.VoiceOverEvents2D.ProgressEarlyWinning, mod.GetTeam(1));

    // The reliable fallback when a voice line will not play.
    if (stinger !== undefined) mod.PlaySound(stinger, 1);
}

// A boot beacon: the first thing to add when the site says "Action Needed" or
// when your mod saves cleanly but nothing happens in game.
//
// "Action Needed" almost always means the script did not load, not that a rule
// is wrong. This tells the two apart. If you see the beacon, the script is
// running and the problem is in your logic. If you do not, the script never
// started and the fault is in the bundle, the strings file or the spatial file.
//
// Bump BUILD every time you upload. Seeing an old number is how you catch the
// case where the site is still serving the previous bundle.

const BUILD = 7;

export function OnGameModeStarted(): void {
    // Goes to the server log, which you can read with the developer console.
    console.log("mod booted, build " + BUILD);

    // Goes on screen, so you can check it without a console.
    mod.DisplayHighlightedWorldLogMessage(mod.Message(mod.stringkeys.faq.boot.line, BUILD));
}

export function OnPlayerDeployed(eventPlayer: mod.Player): void {
    // A second beacon, because a script can boot and still fail later.
    mod.DisplayNotificationMessage(mod.Message(mod.stringkeys.faq.boot.line, BUILD), eventPlayer);
}

// A startup self check for the object ids your script depends on.
//
// When a save is refused with INVALID_ARGUMENT, or the mod saves but a rule
// silently does nothing, the cause is very often an id in the script that no
// longer matches anything in the map: an object was deleted, renamed or
// duplicated in the editor. The site will not tell you which one.
//
// List every id the script needs here. On the first run each one is looked up
// and logged, so a broken reference appears as one line in the log instead of a
// rule that quietly never fires.

const REQUIRED_SPATIAL_IDS: number[] = [100, 101, 102];
const REQUIRED_AREA_TRIGGER_IDS: number[] = [200];
const REQUIRED_CAPTURE_POINT_IDS: number[] = [300, 301];

function report(kind: string, id: number, actualId: number): void {
    // GetObjId on the object you looked up should give the id back. A different
    // number, or 0, means nothing in the map answers to that id.
    if (actualId === id) {
        console.log("ok      " + kind + " " + id);
    } else {
        console.log("MISSING " + kind + " " + id + " (got " + actualId + ")");
    }
}

export function OnGameModeStarted(): void {
    for (const id of REQUIRED_SPATIAL_IDS) {
        report("spatial", id, mod.GetObjId(mod.GetSpatialObject(id)));
    }
    for (const id of REQUIRED_AREA_TRIGGER_IDS) {
        report("areaTrigger", id, mod.GetObjId(mod.GetAreaTrigger(id)));
    }
    for (const id of REQUIRED_CAPTURE_POINT_IDS) {
        report("capturePoint", id, mod.GetObjId(mod.GetCapturePoint(id)));
    }

    // A duplicate id in the map is the other half of the same problem, and it
    // shows up here as two different objects both answering to one number.
    const seen: number[] = [];
    const all = REQUIRED_SPATIAL_IDS.concat(REQUIRED_AREA_TRIGGER_IDS, REQUIRED_CAPTURE_POINT_IDS);
    for (const id of all) {
        if (seen.indexOf(id) !== -1) console.log("DUPLICATE id listed twice: " + id);
        seen.push(id);
    }
}

// Two habits that keep a script under the upload size limit.
//
// The script and the strings file are counted together, and the budget is around
// a megabyte. The spatial file for the map is counted separately. Long argument
// lists and a separate string key per line of text are what fill the budget up.
//
// 1. Wrap the long API calls once and call the wrapper everywhere.
// 2. Reuse one templated string key with arguments instead of writing a key per
//    variation. Ten score lines become one key and one number.

function addLine(name: string, parent: mod.UIWidget, y: number, label: mod.Message): void {
    mod.AddUIText(
        name,
        mod.CreateVector(8, y, 0),
        mod.CreateVector(300, 28, 0),
        mod.UIAnchor.TopLeft,
        parent,
        true,
        0,
        mod.CreateVector(0, 0, 0),
        0,
        mod.UIBgFill.None,
        label,
        20,
        mod.CreateVector(1, 1, 1),
        1,
        mod.UIAnchor.CenterLeft,
        mod.UIDepth.AboveGameUI
    );
}

export function OnGameModeStarted(): void {
    mod.AddUIContainer(
        "faqBoard",
        mod.CreateVector(24, 24, 0),
        mod.CreateVector(320, 140, 0),
        mod.UIAnchor.TopLeft,
        mod.GetUIRoot(),
        true,
        8,
        mod.CreateVector(0, 0, 0),
        0.7,
        mod.UIBgFill.Solid,
        mod.UIDepth.AboveGameUI
    );

    const board = mod.FindUIWidgetWithName("faqBoard") as mod.UIWidget;

    // Four rows, one wrapper call each, and ONE string key shared by all of them.
    for (let i = 0; i < 4; i++) {
        addLine("faqRow" + i, board, i * 30, mod.Message(mod.stringkeys.faq.board.row, i + 1, 0));
    }
}
